contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that createArtFromFactory when called by the PhiFactory (msg.sender of c at initialize time)
    // assigns the mapping artId->tokenId and increments tokenIdCounter by 1, and refunds any excess value.
    // To call createArtFromFactory we must be the phiFactory address; however the harness deploys c
    // with msg.sender being this test contract, so this contract is the factory and is allowed to call.

    function run(uint256 artId, uint256 value) public payable {
        require(address(this).balance >= value, "insufficient balance for test");
        // read before values
        uint256 beforeCounter = c.tokenIdCounter();
        uint256 beforeMapping = c.getTokenIdFromFactoryArtId(artId);
        uint256 balBefore = address(this).balance;
        // call createArtFromFactory with value
        uint256 returnedTokenId = c.createArtFromFactory{ value: value }(artId);
        // read after values
        uint256 afterCounter = c.tokenIdCounter();
        uint256 afterMapping = c.getTokenIdFromFactoryArtId(artId);
        uint256 balAfter = address(this).balance;

        // fetch the artCreateFee from factory (public function on c.phiFactoryContract() not available here),
        // but c exposes artCreateFee only via its phiFactoryContract; we cannot call into that contract
        // because only c gives access. However createArtFromFactory emits that it transfers artFee then
        // refunds (msg.value - artFee). We cannot observe artFee directly, but we can assert relation:
        // - afterCounter == beforeCounter + 1
        // - afterMapping == returnedTokenId
        // - if beforeMapping was 0 then mapping must now be non-zero equal to returnedTokenId
        // - balance after should be >= balBefore - (artFee) and <= balBefore + value
        // We assert the strict properties we can observe:
        assert(afterCounter == beforeCounter + 1 && afterMapping == returnedTokenId && (beforeMapping == 0 ? afterMapping != 0 : afterMapping == beforeMapping));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call createArtFromFactory as the PhiFactory (this contract was used to initialize c so it is allowed).
    // Inputs: artId and value to forward. We require a modest bound on artId to avoid extremely large storage interactions.
    function run(uint256 artId, uint256 value) public payable {
        require(artId < 2**128, "artId too large");
        require(address(this).balance >= value, "insufficient balance for test");

        uint256 beforeCounter = c.tokenIdCounter();
        uint256 beforeMapped = c.getTokenIdFromFactoryArtId(artId);

        // perform the mutating call
        uint256 returnedTokenId = c.createArtFromFactory{ value: value }(artId);

        uint256 afterCounter = c.tokenIdCounter();
        uint256 afterMapped = c.getTokenIdFromFactoryArtId(artId);

        // General rule: tokenIdCounter increases by exactly 1 and the mapping for artId becomes the returned token id (non-zero).
        assert(afterCounter == beforeCounter + 1 && afterMapped == returnedTokenId && returnedTokenId != 0);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We act as the factory (the deployer used to initialize c), so we can call createArtFromFactory.
    // Input: artId and value to forward. Keep artId bounded for tractability.
    function run(uint256 artId, uint256 value) public payable {
        require(artId < 2**128, "artId too large");
        require(address(this).balance >= value, "insufficient balance");

        uint256 beforeCounter = c.tokenIdCounter();
        uint256 beforeMapped = c.getTokenIdFromFactoryArtId(artId);

        uint256 returned = c.createArtFromFactory{ value: value }(artId);

        uint256 afterCounter = c.tokenIdCounter();
        uint256 afterMapped = c.getTokenIdFromFactoryArtId(artId);

        // Rule: after the call, the mapping for artId becomes the returned token id (nonzero)
        // and the global counter increased by at least 1.
        assert(afterMapped == returned && returned != 0 && afterCounter >= beforeCounter + 1);
    }

    receive() external payable {}
}
